/* @lc app=leetcode id=2493 lang=kotlin */
class Solution { fun magnificentSets(n: Int, edges: Array<IntArray>): Int = (0 until n).map { mutableListOf<Int>() }.also { adj -> edges.forEach { e -> adj[e[0]-1].add(e[1]-1).also { adj[e[1]-1].add(e[0]-1) } } }.let { adj -> IntArray(n) { -1 }.let { colors -> mutableSetOf<Int>().let { vis -> (0 until n).map { i -> if (i in vis) null else mutableListOf(i).let { q -> 0.also { colors[i] = it }.let { generateSequence(q) { curQ -> if (curQ.isEmpty() || curQ[0] == -1) null else curQ.removeAt(0).let { u -> adj[u].forEach { v -> if (colors[v] == -1) (1 - colors[u]).also { colors[v] = it }.also { curQ.add(v) } else if (colors[v] == colors[u]) (-1).also { curQ.clear() }.also { curQ.add(-1) } } }.let { curQ } }.last().let { resQ -> if (resQ.isNotEmpty() && resQ[0] == -1) null else mutableSetOf(i).also { comp -> generateSequence(listOf(i)) { q2 -> if (q2.isEmpty()) null else q2.flatMap { u -> adj[u].filter { it !in comp } }.distinct().also { comp.addAll(it) } }.last() }.also { vis.addAll(it) } } } } }.let { comps -> if (comps.any { it == null }) -1 else comps.filterNotNull().sumOf { comp -> comp.maxOf { s -> generateSequence(setOf(s) to setOf(s)) { (lvl, visited) -> lvl.flatMap { adj[it] }.filter { it !in visited }.toSet().let { next -> if (next.isEmpty()) null else next to (visited + next) } }.count() } } } } } } }